// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address ownerCandidate, address attackerEOA) public {
        vm.assume(ownerCandidate != address(0));
        vm.assume(attackerEOA != address(0));
        vm.assume(attackerEOA != ownerCandidate);

        vm.prank(address(this));
        c.setOwner(ownerCandidate);
        Caller caller = new Caller(c);

        vm.prank(attackerEOA);
        bool ok = caller.attemptSetOwner(ownerCandidate);

        assertTrue(ok == false);
    }
}

contract Caller {
    Owned immutable c;
    constructor(Owned _c) { c = _c; }
    function attemptSetOwner(address newOwner) external returns (bool) {
        try c.setOwner(newOwner) {
            return true;
        } catch {
            return false;
        }
    }
}
